                            ENVIAR COMPROBANTE (WHATSAPP)
                        </button>
                    ) : (
                        <div className="bg-zinc-900 p-3 text-center text-zinc-500 text-xs font-mono-tech border border-zinc-800">
                            NO SE REGISTRÓ NÚMERO DE TELÉFONO
                        </div>
                    )}

                    <button 
                        onClick={onShowQr}
                        className="w-full bg-zinc-900 hover:bg-zinc-800 text-white font-tech font-bold uppercase py-4 border border-zinc-700 hover:border-white flex items-center justify-center gap-3 transition-all"
                    >
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v1m6 11h2m-6 0h-2v4h-4v-2h-4v2H4v-4H2v-4h2V8h4V4h4v2h2v4h4v2h2v4H18z" /></svg>
                        VER / COMPARTIR CÓDIGO QR
                    </button>
                </div>
            </div>

            <button 
                onClick={onClose} 
                className="w-full bg-black hover:bg-zinc-900 text-zinc-400 hover:text-white font-tech font-bold uppercase py-4 border-t border-zinc-800 transition-colors text-xs tracking-widest"
