export default RegistrationSuccessModal;

import React, { useState } from 'react';
import { Client, Package, PaymentMethod } from '../types';
import { renewClientMembership } from '../services/storage';
import { useToast } from '../context/ToastContext';

interface RenewalModalProps {
  client: Client;
  packages: Package[];
  userName: string;
  onClose: () => void;
  // Actualizamos onSuccess para que reciba datos de la transacción
  onSuccess: (amount: number, concept: string, startDate: string, endDate: string) => void;
}

const RenewalModal: React.FC<RenewalModalProps> = ({ client, packages, userName, onClose, onSuccess }) => {
    const { showToast } = useToast();
    const [selectedPkgId, setSelectedPkgId] = useState(client.package_id || (packages.length > 0 ? packages[0].id : ''));
    const [cost, setCost] = useState<number>(() => {
        const pkg = packages.find(p => p.id === client.package_id);
        return pkg ? pkg.cost : (packages.length > 0 ? packages[0].cost : 0);
    });

    // Default duration calculation
    const calculateEndDate = (days: number) => {
        const d = new Date();
        d.setDate(d.getDate() + days);
        return d.toISOString().split('T')[0];
    };

    const [startDate, setStartDate] = useState(new Date().toISOString().split('T')[0]);
    const [endDate, setEndDate] = useState(() => {
        const pkg = packages.find(p => p.id === selectedPkgId);
        return pkg ? calculateEndDate(pkg.duration_days) : new Date().toISOString().split('T')[0];
    });

    const [paymentMethod, setPaymentMethod] = useState<PaymentMethod>(PaymentMethod.CASH);
    const [isSubmitting, setIsSubmitting] = useState(false);

    const handlePackageChange = (id: string) => {
        setSelectedPkgId(id);
        const pkg = packages.find(p => p.id === id);
        if (pkg) {
            setCost(pkg.cost);
            // Recalculate end date based on new package duration from TODAY
            const d = new Date(startDate);
            d.setDate(d.getDate() + pkg.duration_days);
            setEndDate(d.toISOString().split('T')[0]);
        }
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (isSubmitting) return;

        setIsSubmitting(true);
        try {
            await renewClientMembership(
                client.id,
                startDate,
                endDate,
                selectedPkgId,
                cost,
                paymentMethod,
                userName
            );

            showToast('RENOVACIÓN EXITOSA', 'success');

            // Obtener nombre del paquete para el concepto
            const pkgName = packages.find(p => p.id === selectedPkgId)?.name || 'RENOVACIÓN PERSONALIZADA';

            // Pasar datos al padre
            onSuccess(cost, pkgName, startDate, endDate);

        } catch (error: any) {
            console.error(error);
            showToast('Error al renovar: ' + error.message, 'error');
            setIsSubmitting(false);
        }
    };

    const labelStyle = "block text-xs font-tech text-yellow-500/80 mb-2 uppercase tracking-widest";
    const inputStyle = "w-full bg-black/50 border-2 border-zinc-700 px-4 py-3 text-white focus:border-yellow-500 outline-none font-mono-tech";

    return (
        <div className="fixed inset-0 z-[100] bg-black/90 backdrop-blur-sm flex items-center justify-center p-4 animate-[fadeIn_0.3s_ease-out]">
            <div className="bg-zinc-950 border-2 border-yellow-500 w-full max-w-lg p-8 shadow-[0_0_50px_rgba(234,179,8,0.2)] relative">
                <button onClick={onClose} className="absolute top-4 right-4 text-zinc-500 hover:text-white">✕</button>

                <h2 className="text-2xl font-tech font-bold text-white mb-1 uppercase">RENOVAR MEMBRESÍA</h2>
                <p className="text-zinc-500 font-mono-tech text-xs mb-8 uppercase">CLIENTE: <span className="text-white font-bold">{client.firstName} {client.lastNamePaternal}</span></p>

                <form onSubmit={handleSubmit} className="space-y-6">
                    <div>
                        <label className={labelStyle}>SELECCIONAR PLAN / PAQUETE</label>
                        <select 
                            value={selectedPkgId || ''} 
                            onChange={e => handlePackageChange(e.target.value)} 
                            className={inputStyle}
                        >
                            {packages.map(p => (
                                <option key={p.id} value={p.id}>{p.name} - ${p.cost}</option>
                            ))}
                        </select>
                    </div>

                    <div className="grid grid-cols-2 gap-4">
                        <div>
                            <label className={labelStyle}>INICIO VIGENCIA</label>
                            <input 
                                type="date" 
                                value={startDate} 
                                onChange={e => {
                                    setStartDate(e.target.value);
                                    // Optional: Recalculate end date if desired when start changes
                                }} 
                                className={inputStyle} 
                            />
                        </div>
                        <div>
                            <label className={labelStyle}>FIN VIGENCIA</label>
                            <input 
                                type="date" 
                                value={endDate} 
                                onChange={e => setEndDate(e.target.value)} 
                                className={inputStyle} 
                            />
                        </div>
                    </div>

                    <div className="grid grid-cols-2 gap-4">
                         <div>
                            <label className={labelStyle}>MONTO A COBRAR</label>
                            <div className="relative">
                                <span className="absolute left-3 top-3 text-emerald-500">$</span>
                                <input 
                                    type="number" 
                                    value={cost} 
                                    onChange={e => setCost(parseFloat(e.target.value))} 
                                    className={`${inputStyle} pl-8 text-emerald-400 font-bold border-emerald-500/30`} 
                                />
                            </div>
                        </div>
                        <div>
                            <label className={labelStyle}>MÉTODO DE PAGO</label>
                            <select 
                                value={paymentMethod} 
                                onChange={e => setPaymentMethod(e.target.value as PaymentMethod)} 
                                className={inputStyle}
                            >
                                <option value={PaymentMethod.CASH}>EFECTIVO</option>
                                <option value={PaymentMethod.CARD}>TARJETA</option>
                                <option value={PaymentMethod.TRANSFER}>TRANSFERENCIA</option>
                            </select>
                        </div>
                    </div>

                    <div className="pt-6 border-t border-zinc-800">
                        <button 
                            type="submit" 
                            disabled={isSubmitting}
                            className="w-full bg-yellow-500 text-black font-tech font-bold uppercase tracking-widest px-6 py-4 hover:bg-yellow-400 active:translate-y-1 active:shadow-none transition-all shadow-[0_0_20px_rgba(234,179,8,0.4)] disabled:opacity-50"
                        >
                            {isSubmitting ? 'PROCESANDO PAGO...' : `CONFIRMAR RENOVACIÓN ($${cost})`}
                        </button>
                    </div>
                </form>
            </div>
        </div>
    );
};

export default RenewalModal;

import React, { useState, useMemo, useEffect } from 'react';
import { Client, DashboardMetrics, Package, Activity, UserRole, SystemConfig } from '../types';
import RenewalModal from './RenewalModal';
import PaymentHistoryModal from './PaymentHistoryModal';
import RegistrationSuccessModal from './RegistrationSuccessModal';
import { getSystemConfig, updateSystemConfig, DEFAULT_WA_TEMPLATE, DEFAULT_WA_RECOVERY_TEMPLATE, DEFAULT_WA_WELCOME_TEMPLATE, DEFAULT_WA_RENEWAL_TEMPLATE } from '../services/storage';
import { useToast } from '../context/ToastContext';

interface DashboardProps {
  metrics: DashboardMetrics;
  clients: Client[];
  expiredClients: Client[];
  packages: Package[];
  activities: Activity[];
  userName: string;
  userRole: UserRole;
  allowedActivityIds: string[];
  allowedPackageIds: string[];
  isLoading: boolean;
  onRefreshData: () => void;
  onShowQr?: (client: Client) => void;
  onEditClient?: (client: Client) => void;
  onDeleteClient?: (client: Client) => void;
  onToggleStatus?: (client: Client) => void;
  canRenew: boolean;
  onSwitchCamera?: () => void;
  viewMode: 'DASHBOARD' | 'CLIENTS_DB';
}

type QuickFilterType = 'ALL' | 'EXPIRED_ONLY' | 'EXPIRING' | 'ACTIVE_HEALTHY' | 'ATTENDANCE';
type TemplateType = 'WARNING' | 'RECOVERY' | 'WELCOME' | 'RENEWAL';

const Dashboard: React.FC<DashboardProps> = ({
  metrics,
  clients,
  expiredClients,
  packages,
  activities,
  userName,
  userRole,
  allowedActivityIds,
  allowedPackageIds,
  isLoading,
  onRefreshData,
  onShowQr,
  onEditClient,
  onDeleteClient,
  onToggleStatus,
  canRenew,
  viewMode
}) => {
  const { showToast } = useToast();
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState<'ALL' | 'ACTIVE' | 'INACTIVE'>('ALL');

  // Configuración inicial del filtro:
  const [quickFilter, setQuickFilter] = useState<QuickFilterType>(
      viewMode === 'DASHBOARD' ? 'EXPIRED_ONLY' : 'ALL'
  );

  // Estado para el modal de "Por Vencer"
  const [showExpiringModal, setShowExpiringModal] = useState(false);

  // --- ESTADOS PARA GESTIÓN DE PLANTILLAS ---
  const [config, setConfig] = useState<SystemConfig | null>(null);
  const [isEditingTemplate, setIsEditingTemplate] = useState(false);
  const [activeTemplateTab, setActiveTemplateTab] = useState<TemplateType>('WARNING');
  const [currentTemplateText, setCurrentTemplateText] = useState('');

  // Estados para modales de acción
  const [renewingClient, setRenewingClient] = useState<Client | null>(null);
  const [viewingHistoryClient, setViewingHistoryClient] = useState<Client | null>(null);

  // --- NUEVO: Estado para éxito de renovación ---
  const [renewalSuccessData, setRenewalSuccessData] = useState<{client: Client, amount: number, concept: string} | null>(null);

  // Cargar configuración al montar
  useEffect(() => {
      loadSystemConfig();
  }, []);

  const loadSystemConfig = async () => {
      try {
          const loadedConfig = await getSystemConfig();
          setConfig(loadedConfig);
      } catch (error) {
          console.error("Error loading config", error);
      }
  };

  // Al abrir el editor, cargar el texto de la pestaña activa
  useEffect(() => {
      if (isEditingTemplate && config) {
          switch (activeTemplateTab) {
              case 'WARNING': setCurrentTemplateText(config.wa_template_warning || DEFAULT_WA_TEMPLATE); break;
              case 'RECOVERY': setCurrentTemplateText(config.wa_template_recovery || DEFAULT_WA_RECOVERY_TEMPLATE); break;
              case 'WELCOME': setCurrentTemplateText(config.wa_template_welcome || DEFAULT_WA_WELCOME_TEMPLATE); break;
              case 'RENEWAL': setCurrentTemplateText(config.wa_template_renewal || DEFAULT_WA_RENEWAL_TEMPLATE); break;
          }
      }
  }, [activeTemplateTab, isEditingTemplate, config]);

  const handleSaveTemplate = async () => {
      try {
          const updates: Partial<SystemConfig> = {};

          switch (activeTemplateTab) {
              case 'WARNING': updates.wa_template_warning = currentTemplateText; break;
              case 'RECOVERY': updates.wa_template_recovery = currentTemplateText; break;
              case 'WELCOME': updates.wa_template_welcome = currentTemplateText; break;
              case 'RENEWAL': updates.wa_template_renewal = currentTemplateText; break;
          }

          const newConfig = await updateSystemConfig(updates);
          setConfig(newConfig);
          showToast('PLANTILLA GUARDADA CORRECTAMENTE', 'success');
      } catch (error) {
          showToast('Error al guardar plantilla', 'error');
      }
  };

  const getWhatsAppLink = (client: Client, diffDays: number) => {
      if (!client.phone || !config) return null;

      const cleanPhone = client.phone.replace(/\D/g, '');
      const phone = cleanPhone.length === 10 ? '52' + cleanPhone : cleanPhone;

      let template = '';

      if (diffDays < 0) {
          template = config.wa_template_recovery || DEFAULT_WA_RECOVERY_TEMPLATE;
      } else {
          template = config.wa_template_warning || DEFAULT_WA_TEMPLATE;
      }

      const msg = template
          .replace('{NOMBRE}', client.firstName)
          .replace('{DIAS}', Math.abs(diffDays).toString())
          .replace('{FECHA}', client.membershipEnd);

      return `https://wa.me/${phone}?text=${encodeURIComponent(msg)}`;
  };

  useEffect(() => {
      setQuickFilter(viewMode === 'DASHBOARD' ? 'EXPIRED_ONLY' : 'ALL');
      setStatusFilter('ALL');
  }, [viewMode]);

  const isAdmin = userRole === UserRole.ADMIN;
  const isMonitor = userRole === UserRole.MONITOR;
  const canUserRenew = isAdmin || canRenew;

  const getDaysDiff = (dateStr?: string) => {
      if (!dateStr) return -9999;
      const [y, m, d] = dateStr.split('-').map(Number);
      const end = new Date(y, m - 1, d);
      const now = new Date();
      now.setHours(0,0,0,0);
      return Math.ceil((end.getTime() - now.getTime()) / 864e5);
  };

  const filteredClients = useMemo(() => {
    return clients.filter(client => {
      const matchesSearch = 
        client.firstName.toLowerCase().includes(searchTerm.toLowerCase()) ||
        client.lastNamePaternal.toLowerCase().includes(searchTerm.toLowerCase()) ||
        (client.email && client.email.toLowerCase().includes(searchTerm.toLowerCase()));

      const matchesStatus = 
        statusFilter === 'ALL' ? true :
        statusFilter === 'ACTIVE' ? client.isActive :
        !client.isActive;

      let matchesQuickFilter = true;
      const days = getDaysDiff(client.membershipEnd);

      const isExpired = client.isActive && days < 0; 
      const isExpiringSoon = client.isActive && days >= 0 && days <= 3;
      const isActiveHealthy = client.isActive && days > 3;

      switch (quickFilter) {
          case 'EXPIRED_ONLY': matchesQuickFilter = isExpired; break;
          case 'EXPIRING': matchesQuickFilter = isExpiringSoon; break;
          case 'ACTIVE_HEALTHY': matchesQuickFilter = isActiveHealthy; break;
          case 'ATTENDANCE': matchesQuickFilter = true; break;
          case 'ALL': default: matchesQuickFilter = true; break;
      }

      return matchesSearch && matchesStatus && matchesQuickFilter;
    });
  }, [clients, searchTerm, statusFilter, quickFilter]);

  const expiringClientsList = useMemo(() => {
      return clients.filter(client => {
          const days = getDaysDiff(client.membershipEnd);
          return client.isActive && days >= 0 && days <= 3;
      });
  }, [clients]);

  const totalExpired = clients.filter(c => {
      const d = getDaysDiff(c.membershipEnd);
      return c.isActive && c.membershipEnd && d < 0;
  }).length;

  const handleResetDashboard = () => {
      if (viewMode === 'DASHBOARD') {
          setQuickFilter('EXPIRED_ONLY');
      }
      onRefreshData();
  };

  if (isLoading) {
    return (
      <div className="h-full flex items-center justify-center">
        <div className="text-yellow-500 font-mono-tech animate-pulse text-xl">CARGANDO SISTEMA...</div>
      </div>
    );
  }

  const MetricCard = ({ title, value, subtext, icon, active, onClick, colorClass = "text-white" }: any) => (
      <div 
        onClick={onClick}
        className={`relative bg-black border p-4 cursor-pointer overflow-hidden group transition-all h-32 flex flex-col justify-between
        ${active ? 'border-yellow-500 shadow-[0_0_15px_rgba(234,179,8,0.1)]' : 'border-zinc-800 hover:border-zinc-600'}`}
      >
          <div className="flex justify-between items-start z-10 relative">
              <span className={`text-[10px] font-tech font-bold uppercase tracking-widest ${active ? 'text-yellow-500' : 'text-zinc-500'}`}>
                  {title}
              </span>
              {active && <div className="w-2 h-2 bg-yellow-500 rounded-full animate-pulse"></div>}
          </div>

          <div className={`text-4xl font-mono-tech font-bold ${colorClass} z-10 relative tracking-tighter`}>
              {value}
          </div>

          <div className="text-[10px] text-zinc-600 font-mono-tech z-10 relative truncate">
              {subtext}
          </div>

