                                                    <div className="flex items-center gap-3">
                                                        <div className="w-10 h-10 bg-black border border-zinc-800 flex items-center justify-center overflow-hidden">
                                                            {c.photoUrl ? <img src={c.photoUrl} alt="" className="w-full h-full object-cover" /> : <span className="text-zinc-700">👤</span>}
                                                        </div>
                                                        <div>
                                                            <p className="font-bold text-white uppercase">{c.firstName} {c.lastNamePaternal}</p>
                                                            <p className="text-[10px] text-zinc-500">{c.phone || 'SIN TEL'}</p>
                                                        </div>
                                                    </div>
                                                </td>
                                                <td className="p-4">
                                                    <span className="font-bold text-yellow-500 block text-lg">{c.membershipEnd}</span>
                                                    <span className="text-xs text-zinc-500">{diff === 0 ? 'VENCE HOY' : `Faltan ${diff} días`}</span>
                                                </td>
                                                <td className="p-4 text-zinc-400">{c.packageName || c.activityName || 'N/A'}</td>
                                                <td className="p-4 pr-6 text-right">
                                                    <div className="flex justify-end gap-2">
                                                        {waLink && (
                                                            <a href={waLink} target="_blank" rel="noreferrer" className="bg-emerald-900/30 text-emerald-500 border border-emerald-500/50 hover:bg-emerald-600 hover:text-white px-3 py-2 text-xs font-bold uppercase transition-all flex items-center gap-2">WHATSAPP</a>
                                                        )}
                                                        {canUserRenew && (
                                                            <button onClick={() => { setShowExpiringModal(false); setRenewingClient(c); }} className="bg-yellow-500 text-black border border-yellow-600 hover:bg-yellow-400 px-3 py-2 text-xs font-bold uppercase transition-all">RENOVAR</button>
                                                        )}
                                                    </div>
                                                </td>
                                            </tr>
                                        );
                                    })
                                )}
                            </tbody>
                          </table>
                      )}
                  </div>

                  <div className="p-4 border-t border-zinc-800 bg-black flex justify-end">
                      <button onClick={() => setShowExpiringModal(false)} className="px-6 py-3 bg-zinc-800 text-white font-bold uppercase text-xs hover:bg-zinc-700 border border-zinc-600">CERRAR LISTADO</button>
                  </div>
              </div>
          </div>
      )}

      {/* RENEWAL MODAL */}
      {renewingClient && (
        <RenewalModal 
            client={renewingClient}
            packages={packages}
            userName={userName}
            onClose={() => setRenewingClient(null)}
            onSuccess={(amount, concept, startDate, endDate) => {
                // Preparamos los datos para el modal de éxito
                const updatedClient = {
                    ...renewingClient,
                    membershipStart: startDate,
                    membershipEnd: endDate
                };

                setRenewalSuccessData({
                    client: updatedClient,
                    amount: amount,
                    concept: concept
                });

                setRenewingClient(null);
                onRefreshData();
            }}
        />
      )}

      {/* RENEWAL SUCCESS MODAL (Reutilizamos RegistrationSuccessModal con modo 'RENEWAL') */}
      {renewalSuccessData && (
          <RegistrationSuccessModal 
              type="RENEWAL"
              client={renewalSuccessData.client}
              paymentAmount={renewalSuccessData.amount}
              paymentConcept={renewalSuccessData.concept}
              onClose={() => setRenewalSuccessData(null)}
              onShowQr={() => { 
                  // Opcional: Mostrar QR si se desea, aunque usualmente ya lo tienen
                  if(onShowQr) onShowQr(renewalSuccessData.client);
                  setRenewalSuccessData(null);
              }}
          />
      )}

      {viewingHistoryClient && (
          <PaymentHistoryModal 
            client={viewingHistoryClient}
            onClose={() => setViewingHistoryClient(null)}
          />
      )}
    </div>
  );
};

export default Dashboard;

