              client={renewalSuccessData.client}
              paymentAmount={renewalSuccessData.amount}
              paymentConcept={renewalSuccessData.concept}
              onClose={() => setRenewalSuccessData(null)}
              onShowQr={() => { 
                  if(onShowQr) onShowQr(renewalSuccessData.client);
                  setRenewalSuccessData(null);
              }}
          />
      )}

      {viewingHistoryClient && (
          <PaymentHistoryModal 
            client={viewingHistoryClient}
            onClose={() => setViewingHistoryClient(null)}
          />
      )}
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect, useCallback } from 'react';
import { UserRole, Client, Package, Activity, DashboardMetrics, AccessStatus } from './types';
import Login from './components/Login';
import Dashboard from './components/Dashboard';
import PointOfSale from './components/PointOfSale';
import FinancePanel from './components/FinancePanel';
import CoachManagement from './components/CoachManagement';
import InventoryPanel from './components/InventoryPanel';
import SystemConfigPanel from './components/SystemConfig';
import ServicesPanel from './components/ServicesPanel'; 
import EditClientModal from './components/EditClientModal';
import QrScanner from './components/QrScanner';
import Camera from './components/Camera';
import QrCodeModal from './components/QrCodeModal';
import RegistrationSuccessModal from './components/RegistrationSuccessModal';
import ConfirmationModal from './components/ConfirmationModal';
import AddExpenseModal from './components/AddExpenseModal'; // Imported
import { 
  getClients, 
  getPackages, 
  getActivities, 
  getTodaysAttendance, 
  getMonthlyRevenue, 
  getDailyShiftRevenue,
  addPayment,
  logAttendance,
  getPackageActivityRelations,
  deleteClient,
  setClientActiveStatus,
  validateSessionUser
} from './services/storage';
import { useToast } from './context/ToastContext';
import { audioService } from './services/audioService';

const App: React.FC = () => {
  const { showToast } = useToast();

  // Auth State
  const [isAuthenticated, setIsAuthenticated] = useState(() => !!localStorage.getItem('userRole'));
  const [userRole, setUserRole] = useState<UserRole>(() => (localStorage.getItem('userRole') as UserRole) || UserRole.COACH);
  const [userName, setUserName] = useState(() => localStorage.getItem('userName') || '');

  // Permissions State
  const [allowedActivityIds, setAllowedActivityIds] = useState<string[]>(() => {
      const stored = localStorage.getItem('allowedActivityIds');
      return stored ? JSON.parse(stored) : [];
  });
  const [allowedPackageIds, setAllowedPackageIds] = useState<string[]>(() => {
      const stored = localStorage.getItem('allowedPackageIds');
      return stored ? JSON.parse(stored) : [];
  });
  const [canRenew, setCanRenew] = useState(() => {
      const stored = localStorage.getItem('canRenew');
      return stored ? JSON.parse(stored) : false;
  });

  // App State
  const [activeTab, setActiveTab] = useState<'DASHBOARD' | 'REGISTER' | 'POS' | 'SCAN' | 'FINANCE' | 'ADMIN' | 'INVENTORY' | 'CONFIG' | 'CLIENTS' | 'SERVICES'>('DASHBOARD');
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [scanMode, setScanMode] = useState<'MENU' | 'QR'>('MENU');

  // Data State
  const [clients, setClients] = useState<Client[]>([]);
  const [packages, setPackages] = useState<Package[]>([]);
  const [activities, setActivities] = useState<Activity[]>([]);
  const [pkgRelations, setPkgRelations] = useState<{package_id: string, activity_id: string}[]>([]); 

  const [metrics, setMetrics] = useState<DashboardMetrics>({
    activeClientsCount: 0,
    todaysAttendanceCount: 0,
    expiringSoonCount: 0,
    monthlyRevenue: 0,
    dailyRevenue: 0
  });
  const [isLoading, setIsLoading] = useState(false);

  // Modals & Camera State
  const [stream, setStream] = useState<MediaStream | null>(null);
  const [cameraError, setCameraError] = useState<string | null>(null);
  const [facingMode, setFacingMode] = useState<'user' | 'environment'>('user'); 
  const [videoDevices, setVideoDevices] = useState<MediaDeviceInfo[]>([]);
  const [selectedDeviceId, setSelectedDeviceId] = useState<string>('');

  const [editingClient, setEditingClient] = useState<Client | null>(null);
  const [showQrModalClient, setShowQrModalClient] = useState<Client | null>(null);

  // Confirmation Modal State
  const [clientToDelete, setClientToDelete] = useState<Client | null>(null);
  const [isDeleting, setIsDeleting] = useState(false);

  // Registration Success
  const [registeredClient, setRegisteredClient] = useState<Client | null>(null);

  // Expense Modal State
  const [isExpenseModalOpen, setIsExpenseModalOpen] = useState(false);

  // Initialize Camera
  const initCamera = useCallback(async () => {
    try {
      if (stream) {
        stream.getTracks().forEach(t => t.stop());
      }

      // Definir constraints: Si hay un ID seleccionado explícitamente, usarlo. Si no, usar facingMode.
      const constraints = {
        video: selectedDeviceId 
            ? { deviceId: { exact: selectedDeviceId }, width: { ideal: 1280 }, height: { ideal: 720 } }
            : { facingMode: facingMode, width: { ideal: 1280 }, height: { ideal: 720 } },
        audio: false
      };

      const newStream = await navigator.mediaDevices.getUserMedia(constraints);
      setStream(newStream);
      setCameraError(null);

      // Enumerar dispositivos una vez que tenemos permisos
      const devices = await navigator.mediaDevices.enumerateDevices();
      const videoInputs = devices.filter(device => device.kind === 'videoinput');
      setVideoDevices(videoInputs);

    } catch (err) {
      console.warn("Camera init failed:", err);
      setCameraError('ACCESO A CÁMARA DENEGADO O NO DISPONIBLE');
    }
  }, [facingMode, selectedDeviceId]);

  // Toggle Camera Function
  const toggleCamera = () => {
      setSelectedDeviceId('');
      setFacingMode(prev => prev === 'user' ? 'environment' : 'user');
  };

  const handleDeviceSelect = (deviceId: string) => {
      setSelectedDeviceId(deviceId);
  };

  // CHECK SESSION VALIDITY ON MOUNT
  useEffect(() => {
      const verifySession = async () => {
          if (isAuthenticated) {
              const email = localStorage.getItem('userEmail'); 
              if (email) {
                  const isValid = await validateSessionUser(email);
                  if (!isValid) {
                      handleLogout();
                      showToast('Sesión expirada o usuario desactivado', 'warning');
                  }
              }
              const unlockAudio = () => {
                audioService.init();
                window.removeEventListener('click', unlockAudio);
              };
              window.addEventListener('click', unlockAudio);
          }
      };
      verifySession();
  }, [isAuthenticated]);

  useEffect(() => {
    if (isAuthenticated) {
      initCamera();
    }
    return () => {
      if (stream) stream.getTracks().forEach(t => t.stop());
    };
  }, [isAuthenticated, initCamera]);

  const loadData = useCallback(async () => {
    setIsLoading(true);
    try {
      const [clientsData, packagesData, activitiesData, attendanceData, monthlyRev, dailyRev, relationsData] = await Promise.all([
        getClients(),
        getPackages(),
        getActivities(),
        getTodaysAttendance(),
        getMonthlyRevenue(),
        getDailyShiftRevenue(),
        getPackageActivityRelations()
      ]);

      setClients(clientsData);
      setPackages(packagesData);
      setActivities(activitiesData);
      setPkgRelations(relationsData);

      const expiringSoon = clientsData.filter(c => {
        if (!c.membershipEnd || !c.isActive) return false;
        const [y, m, d] = c.membershipEnd.split('-').map(Number);
        const end = new Date(y, m - 1, d);
        const now = new Date();
        now.setHours(0,0,0,0);
        const days = Math.ceil((end.getTime() - now.getTime()) / 864e5);
        return days >= 0 && days <= 3;
      }).length;

      setMetrics({
        activeClientsCount: clientsData.filter(c => c.isActive).length,
        todaysAttendanceCount: new Set(attendanceData.map(a => a.client_id)).size,
        expiringSoonCount: expiringSoon,
        monthlyRevenue: monthlyRev,
        dailyRevenue: dailyRev
      });

    } catch (error: any) {
      console.error("Error loading data:", error);
      const errorMessage = error?.message || (typeof error === 'object' ? JSON.stringify(error) : String(error));
      showToast(`Error de sistema: ${errorMessage}`, 'error');
    } finally {
      setIsLoading(false);
    }
  }, [showToast]);

  useEffect(() => {
    if (isAuthenticated) {
      loadData();
    }
  }, [isAuthenticated, loadData]);

  const handleLoginSuccess = (role: UserRole, name: string, activities: string[], packages: string[], canRenewVal: boolean) => {
    setUserRole(role);
    setUserName(name);
    setAllowedActivityIds(activities);
    setAllowedPackageIds(packages);
    setCanRenew(canRenewVal);

    localStorage.setItem('userRole', role);
    localStorage.setItem('userName', name);
    localStorage.setItem('allowedActivityIds', JSON.stringify(activities));
    localStorage.setItem('allowedPackageIds', JSON.stringify(packages));
    localStorage.setItem('canRenew', JSON.stringify(canRenewVal));

    setIsAuthenticated(true);
    const unlockAudio = () => {
        audioService.init();
        window.removeEventListener('click', unlockAudio);
    };
    window.addEventListener('click', unlockAudio);
  };

  const handleLogout = () => {
    if (stream) {
        stream.getTracks().forEach(track => track.stop());
        setStream(null);
    }
    localStorage.clear();
    sessionStorage.clear(); 

    setUserName('');
    setUserRole(UserRole.COACH);
    setAllowedActivityIds([]);
    setAllowedPackageIds([]);
    setCanRenew(false);
    setIsAuthenticated(false);
  };

  const handleRegisterSuccess = async (newClient?: Client) => {
    await loadData();
    if (newClient) {
        if (newClient.cost && newClient.cost > 0) {
            const pkgName = packages.find(p => p.id === newClient.package_id)?.name;
            const actName = activities.find(a => a.id === newClient.activity_id)?.name;
            const conceptDetail = pkgName || actName || 'Registro';

            try {
                await addPayment({
                    client_id: newClient.id,
                    amount: newClient.cost,
                    method: 'EFECTIVO' as any,
                    concept: `INSCRIPCIÓN/MENSUALIDAD: ${conceptDetail}`,
                    created_by: userName
                });
            } catch (e) {
                console.error("Error creating initial payment record", e);
            }
        }
        setRegisteredClient(newClient);
    }
    setActiveTab('DASHBOARD');
  };

  const handleScanSuccess = async (scannedValue: string) => {
     const client = clients.find(c => c.id === scannedValue || scannedValue.includes(c.id));
     if (client) {
         try {
             await logAttendance(client.id);
             audioService.playSuccess();
             showToast(`BIENVENIDO ${client.firstName}`, 'success');
             loadData(); 
         } catch (e) {
             audioService.playWarning();
             showToast('YA REGISTRADO O ERROR', 'warning');
         }
     } else {
         audioService.playAlarm();
         showToast('CLIENTE NO ENCONTRADO', 'error');
     }
  };

  const handleDeleteClient = (client: Client) => {
      setClientToDelete(client);
  };

  const executeDeleteClient = async () => {
      if (!clientToDelete) return;
      setIsDeleting(true);
      try {
          await deleteClient(clientToDelete);
          showToast('CLIENTE ELIMINADO', 'success');
          await loadData();
      } catch (error: any) {
          console.error(error);
          showToast('Error al eliminar: ' + error.message, 'error');
      } finally {
          setIsDeleting(false);
          setClientToDelete(null);
      }
  };

  const handleToggleStatus = async (client: Client) => {
      const newStatus = !client.isActive;
      try {
          await setClientActiveStatus(client.id, newStatus);
          showToast(`CLIENTE ${newStatus ? 'ACTIVADO' : 'DESACTIVADO'}`, 'info');
          loadData();
      } catch (error: any) {
          console.error(error);
          showToast('Error al cambiar estado', 'error');
      }
  };

  if (!isAuthenticated) {
    const onLoginWrapper = (role: UserRole, name: string, activities: string[], packages: string[], canRenew: boolean) => {
        handleLoginSuccess(role, name, activities, packages, canRenew);
    };
    return <Login onLoginSuccess={onLoginWrapper} />;
  }

  return (
    <div className="min-h-screen bg-black text-zinc-100 flex flex-col font-sans selection:bg-yellow-500 selection:text-black overflow-hidden">

      {/* DESKTOP SIDEBAR - COMPACT VERSION */}
      <aside className="hidden lg:flex fixed top-0 left-0 h-full w-64 bg-zinc-950 border-r border-zinc-800 flex-col z-50">
          <div className="p-5 border-b border-zinc-900">
              <h1 className="text-2xl font-tech font-black text-white tracking-tighter">KALI <span className="text-yellow-500">ACCESS</span></h1>
              <p className="text-[10px] text-zinc-500 font-mono-tech mt-1 tracking-widest">{userRole} :: {userName}</p>
          </div>

          <nav className="flex-1 p-2 space-y-1 overflow-y-auto custom-scrollbar">
              <button onClick={() => setActiveTab('DASHBOARD')} className={`w-full text-left px-3 py-2 font-tech font-bold uppercase tracking-widest text-xs transition-all border-l-2 ${activeTab === 'DASHBOARD' ? 'border-yellow-500 text-yellow-500 bg-yellow-900/10' : 'border-transparent text-zinc-500 hover:text-white hover:bg-zinc-900'}`}>DASHBOARD</button>

              {(userRole === UserRole.ADMIN || userRole === UserRole.COACH) && (
                  <>
                      <button onClick={() => setActiveTab('CLIENTS')} className={`w-full text-left px-3 py-2 font-tech font-bold uppercase tracking-widest text-xs transition-all border-l-2 ${activeTab === 'CLIENTS' ? 'border-yellow-500 text-yellow-500 bg-yellow-900/10' : 'border-transparent text-zinc-500 hover:text-white hover:bg-zinc-900'}`}>BASE DE DATOS</button>
                      <button onClick={() => setActiveTab('REGISTER')} className={`w-full text-left px-3 py-2 font-tech font-bold uppercase tracking-widest text-xs transition-all border-l-2 ${activeTab === 'REGISTER' ? 'border-yellow-500 text-yellow-500 bg-yellow-900/10' : 'border-transparent text-zinc-500 hover:text-white hover:bg-zinc-900'}`}>REGISTRO</button>
                      <button onClick={() => setActiveTab('POS')} className={`w-full text-left px-3 py-2 font-tech font-bold uppercase tracking-widest text-xs transition-all border-l-2 ${activeTab === 'POS' ? 'border-yellow-500 text-yellow-500 bg-yellow-900/10' : 'border-transparent text-zinc-500 hover:text-white hover:bg-zinc-900'}`}>VENTA (POS)</button>
                      <button onClick={() => { setActiveTab('SCAN'); setScanMode('QR'); }} className={`w-full text-left px-3 py-2 font-tech font-bold uppercase tracking-widest text-xs transition-all border-l-2 ${activeTab === 'SCAN' ? 'border-yellow-500 text-yellow-500 bg-yellow-900/10' : 'border-transparent text-zinc-500 hover:text-white hover:bg-zinc-900'}`}>ACCESO QR</button>
                  </>
              )}

              {userRole === UserRole.ADMIN && (
                  <>
                      <div className="my-2 border-t border-zinc-800"></div>
                      <p className="px-3 text-[10px] text-zinc-600 font-tech uppercase mb-1">ADMINISTRACIÓN</p>
                      <button onClick={() => setActiveTab('SERVICES')} className={`w-full text-left px-3 py-2 font-tech font-bold uppercase tracking-widest text-xs transition-all border-l-2 ${activeTab === 'SERVICES' ? 'border-yellow-500 text-yellow-500 bg-yellow-900/10' : 'border-transparent text-zinc-500 hover:text-white hover:bg-zinc-900'}`}>PLANES Y CLASES</button>
                      <button onClick={() => setActiveTab('FINANCE')} className={`w-full text-left px-3 py-2 font-tech font-bold uppercase tracking-widest text-xs transition-all border-l-2 ${activeTab === 'FINANCE' ? 'border-yellow-500 text-yellow-500 bg-yellow-900/10' : 'border-transparent text-zinc-500 hover:text-white hover:bg-zinc-900'}`}>FINANZAS</button>
                      <button onClick={() => setActiveTab('INVENTORY')} className={`w-full text-left px-3 py-2 font-tech font-bold uppercase tracking-widest text-xs transition-all border-l-2 ${activeTab === 'INVENTORY' ? 'border-yellow-500 text-yellow-500 bg-yellow-900/10' : 'border-transparent text-zinc-500 hover:text-white hover:bg-zinc-900'}`}>INVENTARIO</button>
                      <button onClick={() => setActiveTab('ADMIN')} className={`w-full text-left px-3 py-2 font-tech font-bold uppercase tracking-widest text-xs transition-all border-l-2 ${activeTab === 'ADMIN' ? 'border-yellow-500 text-yellow-500 bg-yellow-900/10' : 'border-transparent text-zinc-500 hover:text-white hover:bg-zinc-900'}`}>STAFF / USUARIOS</button>
                      <button onClick={() => setActiveTab('CONFIG')} className={`w-full text-left px-3 py-2 font-tech font-bold uppercase tracking-widest text-xs transition-all border-l-2 ${activeTab === 'CONFIG' ? 'border-yellow-500 text-yellow-500 bg-yellow-900/10' : 'border-transparent text-zinc-500 hover:text-white hover:bg-zinc-900'}`}>SISTEMA</button>
                  </>
