                    const end = new Date(y, m - 1, d);
                    const now = new Date();
                    now.setHours(0,0,0,0);
                    return end < now;
                  })}
                  packages={packages}
                  activities={activities}
                  userName={userName}
                  userRole={userRole}
                  allowedActivityIds={allowedActivityIds}
                  allowedPackageIds={allowedPackageIds}
                  isLoading={isLoading}
                  onRefreshData={loadData}
                  onShowQr={(c) => setShowQrModalClient(c)}
                  onEditClient={(c) => setEditingClient(c)}
                  canRenew={canRenew}
                  onSwitchCamera={toggleCamera} 
                  viewMode="DASHBOARD"
                  onAddExpense={() => setIsExpenseModalOpen(true)}
              />
          )}

          {activeTab === 'CLIENTS' && (
              <Dashboard 
                  metrics={metrics}
                  clients={clients}
                  expiredClients={[]}
                  packages={packages}
                  activities={activities}
                  userName={userName}
                  userRole={userRole}
                  allowedActivityIds={allowedActivityIds}
                  allowedPackageIds={allowedPackageIds}
                  isLoading={isLoading}
                  onRefreshData={loadData}
                  onShowQr={(c) => setShowQrModalClient(c)}
                  onEditClient={(c) => setEditingClient(c)}
                  onDeleteClient={handleDeleteClient}
                  onToggleStatus={handleToggleStatus}
                  canRenew={canRenew}
                  onSwitchCamera={toggleCamera} 
                  viewMode="CLIENTS_DB"
              />
          )}

          {activeTab === 'REGISTER' && (
              <div className="h-full flex items-center justify-center">
                  <EditClientModal 
                      client={{ id: '', firstName: '', lastNamePaternal: '', lastNameMaternal: '', email: '', phone: '', photoUrl: null, isActive: true, membershipStart: '', membershipEnd: '', activity_id: null, cost: 0, package_id: null }}
                      isNew={true}
                      packages={packages}
                      activities={activities}
                      onClose={() => setActiveTab('DASHBOARD')}
                      onSuccess={handleRegisterSuccess}
                      stream={stream}
                      cameraError={cameraError}
                      userRole={userRole}
                      onSwitchCamera={toggleCamera}
                      packageRelations={pkgRelations}
                      availableDevices={videoDevices}
                      currentDeviceId={selectedDeviceId}
                      onDeviceSelect={handleDeviceSelect}
                  />
              </div>
          )}

          {activeTab === 'POS' && <PointOfSale userName={userName} />}

          {activeTab === 'SCAN' && (
              <div className="h-full flex flex-col items-center justify-center">
                  <div className="w-full h-full relative">
                      <QrScanner isActive={true} onScanSuccess={handleScanSuccess} />
                  </div>
              </div>
          )}

          {activeTab === 'SERVICES' && <ServicesPanel />}
          {activeTab === 'FINANCE' && <FinancePanel />}
          {activeTab === 'INVENTORY' && <InventoryPanel />}
          {activeTab === 'ADMIN' && <CoachManagement />}
          {activeTab === 'CONFIG' && <SystemConfigPanel />}
