                                            <td className="p-4 pr-6 text-right">
                                                <div className="flex justify-end gap-2">
                                                    {canUserRenew && (
                                                        <button onClick={() => setRenewingClient(c)} className="bg-yellow-500 hover:bg-yellow-400 text-black px-3 py-1 font-bold text-[10px] uppercase rounded shadow-lg shadow-yellow-500/20">
                                                            RENOVAR AHORA
                                                        </button>
                                                    )}
                                                    <button onClick={() => onEditClient && onEditClient(c)} className="text-zinc-400 hover:text-white border border-zinc-700 px-2 py-1 rounded hover:bg-zinc-800" title="Editar">
                                                        <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z" /></svg>
                                                    </button>
                                                </div>
                                            </td>
                                        </tr>
                                    );
                                })
                            )}
                        </tbody>
                    </table>
                </div>

                <div className="p-4 border-t border-zinc-800 bg-zinc-900/50 flex justify-end">
                     <button onClick={() => setShowExpiringModal(false)} className="px-6 py-2 bg-zinc-800 hover:bg-zinc-700 text-white font-tech uppercase text-xs border border-zinc-600 rounded">Cerrar</button>
                </div>
            </div>
        </div>
      )}

      {/* TEMPLATE EDITOR MODAL (Z-INDEX SUPERIOR) */}
      {isEditingTemplate && (
        <div className="fixed inset-0 z-[100] bg-black/90 backdrop-blur-sm flex items-center justify-center p-4 animate-[fadeIn_0.3s_ease-out]">
            <div className="bg-zinc-950 border-2 border-zinc-800 w-full max-w-2xl p-6 shadow-2xl rounded-lg">
                <h3 className="text-xl font-tech font-bold text-white mb-4 border-b border-zinc-800 pb-2 flex items-center justify-between">
                    <span>EDITOR DE PLANTILLAS WHATSAPP</span>
                    <button onClick={() => setIsEditingTemplate(false)} className="text-zinc-500 hover:text-white">✕</button>
                </h3>

                <div className="flex gap-2 mb-4 overflow-x-auto pb-2 border-b border-zinc-800">
                    <button onClick={() => setActiveTemplateTab('WARNING')} className={`px-3 py-1 text-xs font-bold uppercase transition-all ${activeTemplateTab === 'WARNING' ? 'bg-yellow-500 text-black' : 'text-zinc-500 hover:text-white bg-zinc-900'}`}>RECORDATORIO</button>
                    <button onClick={() => setActiveTemplateTab('RECOVERY')} className={`px-3 py-1 text-xs font-bold uppercase transition-all ${activeTemplateTab === 'RECOVERY' ? 'bg-yellow-500 text-black' : 'text-zinc-500 hover:text-white bg-zinc-900'}`}>VENCIDO</button>
                    <button onClick={() => setActiveTemplateTab('RENEWAL')} className={`px-3 py-1 text-xs font-bold uppercase transition-all ${activeTemplateTab === 'RENEWAL' ? 'bg-yellow-500 text-black' : 'text-zinc-500 hover:text-white bg-zinc-900'}`}>RENOVACIÓN</button>
                    <button onClick={() => setActiveTemplateTab('WELCOME')} className={`px-3 py-1 text-xs font-bold uppercase transition-all ${activeTemplateTab === 'WELCOME' ? 'bg-yellow-500 text-black' : 'text-zinc-500 hover:text-white bg-zinc-900'}`}>BIENVENIDA</button>
                </div>

                <textarea 
                    value={currentTemplateText} 
                    onChange={(e) => setCurrentTemplateText(e.target.value)} 
                    className="w-full h-40 bg-black border border-zinc-700 p-3 text-white font-mono-tech text-sm focus:border-yellow-500 outline-none mb-4"
                    placeholder="Escribe el mensaje..."
                />

                <div className="text-[10px] text-zinc-500 font-mono-tech mb-6 bg-zinc-900 p-3 rounded">
                    <strong className="text-zinc-300">VARIABLES DISPONIBLES:</strong> {`{NOMBRE}, {FECHA}, {DIAS}`}
                    {activeTemplateTab === 'WELCOME' && `, {FECHA_INICIO}, {FECHA_FIN}, {PAGO}, {CONCEPTO}`}
                    {activeTemplateTab === 'RENEWAL' && `, {PLAN}, {PAGO}, {FECHA_FIN}`}
                </div>

                <div className="flex justify-end gap-3">
                    <button onClick={() => setIsEditingTemplate(false)} className="px-4 py-2 bg-zinc-800 text-zinc-400 font-bold text-xs uppercase hover:text-white">CANCELAR</button>
                    <button onClick={handleSaveTemplate} className="px-6 py-2 bg-yellow-500 text-black font-bold text-xs uppercase hover:bg-yellow-400 shadow-lg">GUARDAR PLANTILLA</button>
                </div>
            </div>
        </div>
      )}

      {/* RENEWAL MODAL */}
      {renewingClient && (
        <RenewalModal 
            client={renewingClient}
            packages={packages}
            userName={userName}
            onClose={() => setRenewingClient(null)}
            onSuccess={(amount, concept, startDate, endDate) => {
                const updatedClient = {
                    ...renewingClient,
                    membershipStart: startDate,
                    membershipEnd: endDate
                };

                setRenewalSuccessData({
                    client: updatedClient,
                    amount: amount,
                    concept: concept
                });

                setRenewingClient(null);
                onRefreshData();
            }}
        />
      )}

      {/* RENEWAL SUCCESS MODAL */}
      {renewalSuccessData && (
          <RegistrationSuccessModal 
              type="RENEWAL"
              client={renewalSuccessData.client}
              paymentAmount={renewalSuccessData.amount}
              paymentConcept={renewalSuccessData.concept}
              onClose={() => setRenewalSuccessData(null)}
              onShowQr={() => { 
                  if(onShowQr) onShowQr(renewalSuccessData.client);
                  setRenewalSuccessData(null);
              }}
          />
      )}

      {viewingHistoryClient && (
          <PaymentHistoryModal 
            client={viewingHistoryClient}
            onClose={() => setViewingHistoryClient(null)}
          />
      )}
    </div>
  );
};

export default Dashboard;

import React, { Component, ErrorInfo, ReactNode } from 'react';

interface Props {
  children?: ReactNode;
}

interface State {
  hasError: boolean;
  error: Error | null;
  errorInfo: ErrorInfo | null;
}

class ErrorBoundary extends Component<Props, State> {
  public state: State = {
    hasError: false,
    error: null,
    errorInfo: null
  };

  public static getDerivedStateFromError(error: Error): Partial<State> {
    return { hasError: true, error };
  }

  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    console.error("Uncaught error:", error, errorInfo);
    this.setState({ errorInfo });
  }

  public render(): ReactNode {
    if (this.state.hasError) {
      return (
        <div className="min-h-screen bg-black text-white p-8 flex flex-col items-center justify-center font-mono text-center z-[99999] relative">
          <div className="border-2 border-red-600 bg-red-900/20 p-6 rounded-lg max-w-2xl">
            <h1 className="text-3xl font-bold text-red-500 mb-4">¡ALERTA DE SISTEMA!</h1>
            <p className="text-xl mb-4">La aplicación ha detectado un error crítico.</p>

            <div className="bg-black/50 p-4 rounded text-left overflow-auto max-h-60 border border-zinc-700 mb-6">
              <p className="text-red-400 font-bold mb-2">Error: {this.state.error?.toString()}</p>
              <pre className="text-xs text-zinc-500 whitespace-pre-wrap">
                {this.state.errorInfo?.componentStack}
              </pre>
            </div>

            <button
              onClick={() => {
                  sessionStorage.clear();
                  window.location.reload();
              }}
              className="bg-red-600 hover:bg-red-500 text-white font-bold py-3 px-6 rounded uppercase tracking-widest"
            >
              Reiniciar Sistema (Hard Reset)
            </button>
          </div>
        </div>
      );
    }

    return this.props.children;
  }
}

export default ErrorBoundary;

import React, { useEffect, useState } from 'react';
import { Payment, PaymentMethod, Expense } from '../types';
import { getPayments, getExpenses } from '../services/storage';

interface ShiftDetailsModalProps {
  onClose: () => void;
}

type TransactionItem = 
  | ({ type: 'PAYMENT' } & Payment)
  | ({ type: 'EXPENSE' } & Expense);

const ShiftDetailsModal: React.FC<ShiftDetailsModalProps> = ({ onClose }) => {
  const [transactions, setTransactions] = useState<TransactionItem[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [netTotal, setNetTotal] = useState(0);
  const [incomeTotal, setIncomeTotal] = useState(0);
  const [expenseTotal, setExpenseTotal] = useState(0);

  useEffect(() => {
    const fetchShiftData = async () => {
      try {
        const now = new Date();
        const start = new Date(now.getFullYear(), now.getMonth(), now.getDate(), 0, 0, 0, 0);
        const end = new Date(now.getFullYear(), now.getMonth(), now.getDate(), 23, 59, 59, 999);

        // Obtener Pagos y Gastos en paralelo
        const [paymentsData, expensesData] = await Promise.all([
            getPayments(start.toISOString(), end.toISOString()),
            getExpenses(start.toISOString(), end.toISOString())
        ]);

        // Unificar y ordenar cronológicamente (más reciente primero)
        const combined: TransactionItem[] = [
            ...paymentsData.map(p => ({ ...p, type: 'PAYMENT' } as const)),
            ...expensesData.map(e => ({ ...e, type: 'EXPENSE' } as const))
        ].sort((a, b) => new Date(b.created_at).getTime() - new Date(a.created_at).getTime());

        setTransactions(combined);

        const inc = paymentsData.reduce((acc, curr) => acc + Number(curr.amount), 0);
        const exp = expensesData.reduce((acc, curr) => acc + Number(curr.amount), 0);

        setIncomeTotal(inc);
        setExpenseTotal(exp);
        setNetTotal(inc - exp);

      } catch (error) {
        console.error("Error cargando detalles del corte:", error);
      } finally {
        setIsLoading(false);
      }
    };

    fetchShiftData();
  }, []);

  return (
    <div 
        className="fixed inset-0 z-[100] bg-black/90 backdrop-blur-sm flex items-center justify-center p-4 animate-[fadeIn_0.3s_ease-out]"
        onClick={onClose}
    >
      <div 
        className="relative w-full max-w-5xl shadow-[0_0_50px_rgba(234,179,8,0.15)] flex flex-col max-h-[90vh] border-2 border-yellow-500"
        style={{ backgroundColor: '#000000' }}
        onClick={(e) => e.stopPropagation()} 
      >
        {/* Header */}
        <div className="p-6 border-b border-white/20 flex justify-between items-start" style={{ backgroundColor: '#000000' }}>
            <div>
                <h2 className="text-2xl font-tech font-bold text-white mb-1">
                    CORTE DE CAJA DETALLADO
                </h2>
                <p className="text-yellow-500 font-mono-tech text-sm font-bold">
                    PERIODO: HOY ({new Date().toLocaleDateString('es-MX')})
                </p>
                <div className="flex gap-4 mt-2 text-xs font-mono-tech">
                    <span className="text-emerald-500">INGRESOS: ${incomeTotal.toLocaleString('es-MX', { minimumFractionDigits: 2 })}</span>
                    <span className="text-zinc-500">|</span>
                    <span className="text-red-500">EGRESOS: ${expenseTotal.toLocaleString('es-MX', { minimumFractionDigits: 2 })}</span>
                </div>
            </div>
            <div className="text-right">
                <p className="text-xs text-zinc-500 font-mono-tech uppercase">TOTAL EN CAJA (NETO)</p>
                <p className={`text-3xl font-bold font-mono-tech ${netTotal >= 0 ? 'text-white' : 'text-red-500'}`}>
                    ${netTotal.toLocaleString('es-MX', { minimumFractionDigits: 2 })}
                </p>
            </div>
        </div>

        {/* Content */}
        <div className="flex-1 overflow-auto p-0" style={{ backgroundColor: '#000000' }}>
             <table className="w-full text-left border-collapse">
                <thead className="sticky top-0 z-10 shadow-md" style={{ backgroundColor: '#000000' }}>
                    <tr className="text-xs font-tech text-zinc-500 uppercase tracking-wider border-b border-white">
                        <th className="p-4">HORA</th>
                        <th className="p-4">CLIENTE / TIPO</th>
                        <th className="p-4">DESCRIPCIÓN / CONCEPTO</th>
                        <th className="p-4">MÉTODO / CATEGORÍA</th>
                        <th className="p-4">REGISTRADO POR</th>
                        <th className="p-4 text-right">MONTO</th>
                    </tr>
                </thead>
                <tbody className="divide-y divide-zinc-800 text-sm font-mono-tech text-white">
                    {isLoading ? (
                        <tr><td colSpan={6} className="p-8 text-center text-yellow-500 animate-pulse font-bold">CARGANDO MOVIMIENTOS...</td></tr>
                    ) : transactions.length === 0 ? (
                        <tr><td colSpan={6} className="p-12 text-center text-zinc-500 font-bold">NO HAY MOVIMIENTOS HOY</td></tr>
                    ) : (
                        transactions.map((item) => {
                            if (item.type === 'PAYMENT') {
                                const p = item as Payment;
                                const isEnrollment = p.concept.toLowerCase().includes('inscripción');
                                const total = Number(p.amount);
                                const enrollmentAmt = isEnrollment ? (total >= 200 ? 200 : 0) : 0; 
                                const planAmt = total - enrollmentAmt;

                                return (
                                    <tr key={`p-${p.id}`} className="hover:bg-zinc-900 transition-colors border-b border-white/10">
                                        <td className="p-4 text-zinc-300">
                                            {new Date(p.created_at).toLocaleTimeString('es-MX', {hour: '2-digit', minute:'2-digit'})}
                                        </td>
                                        <td className="p-4 font-bold text-white">{p.clientName || 'Cliente Eliminado'}</td>
                                        <td className="p-4 text-zinc-300">
                                            {p.concept}
