                                            )}
                                        </td>
                                        <td className="p-4">
                                            <span className={`text-[10px] uppercase px-2 py-1 font-bold border ${
                                                p.method === PaymentMethod.CASH ? 'border-emerald-500 text-emerald-500 bg-emerald-900/10' : 
