              }}
          />
      )}

      {viewingHistoryClient && (
          <PaymentHistoryModal 
            client={viewingHistoryClient}
            onClose={() => setViewingHistoryClient(null)}
          />
      )}

      {/* SHIFT DETAILS MODAL */}
      {showShiftModal && (
          <ShiftDetailsModal onClose={() => setShowShiftModal(false)} />
      )}
    </div>
  );
};

