type QuickFilterType = 'ALL' | 'EXPIRED_ONLY' | 'EXPIRING' | 'ACTIVE_HEALTHY' | 'ATTENDANCE';
type TemplateType = 'WARNING' | 'RECOVERY' | 'WELCOME' | 'RENEWAL';

const Dashboard: React.FC<DashboardProps> = ({
  metrics,
  clients,
  expiredClients,
  packages,
  activities,
  userName,
  userRole,
  allowedActivityIds,
  allowedPackageIds,
  isLoading,
  onRefreshData,
  onShowQr,
  onEditClient,
  onDeleteClient,
